// Browser exploration only. Frozen-model inference uses the exact Python extractor.
export function fft(re,im){const n=re.length;for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j){[re[i],re[j]]=[re[j],re[i]];[im[i],im[j]]=[im[j],im[i]];}}for(let len=2;len<=n;len<<=1){const a=-2*Math.PI/len;for(let i=0;i<n;i+=len)for(let j=0;j<len/2;j++){const c=Math.cos(a*j),s=Math.sin(a*j),k=i+j,h=k+len/2,tr=re[h]*c-im[h]*s,ti=re[h]*s+im[h]*c;re[h]=re[k]-tr;im[h]=im[k]-ti;re[k]+=tr;im[k]+=ti;}}}
export function analyze(samples,sr){
 const n=samples.length;if(!n)throw Error('Audio kosong.');let sum=0,peak=0,clip=0,zcr=0;for(let i=0;i<n;i++){const x=samples[i];if(!Number.isFinite(x))throw Error('Audio mengandung nilai nonfinite.');sum+=x*x;peak=Math.max(peak,Math.abs(x));if(Math.abs(x)>=.999)clip++;if(i&&x*samples[i-1]<0)zcr++;}if(peak<1e-6)throw Error('Audio sunyi; pilih rekaman dengan sinyal.');
 const waveform=Array.from({length:400},(_,i)=>{let m=0;for(let j=Math.floor(i*n/400);j<Math.floor((i+1)*n/400);j++)m=Math.max(m,Math.abs(samples[j]));return m;});
 const size=512,frameSize=Math.round(.025*sr),hop=Math.round(.01*sr),frameCount=Math.floor((n-frameSize)/hop)+1;if(frameCount<1)throw Error('Audio terlalu pendek.');const stride=Math.max(1,Math.ceil(frameCount/400)),mfcc=[],lfcc=[],spectrum=new Array(257).fill(0),spec=[],pitch=[];
 const mel=f=>2595*Math.log10(1+f/700),inv=m=>700*(10**(m/2595)-1);const bank=(isMel)=>Array.from({length:40},(_,j)=>{const e=k=>isMel?inv(mel(sr/2)*k/41):sr/2*k/41;const a=e(j),b=e(j+1),c=e(j+2);return Array.from({length:257},(_,k)=>Math.max(0,Math.min((k*sr/512-a)/(b-a),(c-k*sr/512)/(c-b))));});const banks=[bank(true),bank(false)];let count=0;
 for(let f=0;f<frameCount;f+=stride){const start=f*hop,re=new Float64Array(size),im=new Float64Array(size);for(let j=0;j<Math.min(frameSize,size);j++)re[j]=samples[start+j]*(.5-.5*Math.cos(2*Math.PI*j/(frameSize-1)));fft(re,im);const power=Array.from({length:257},(_,k)=>(re[k]**2+im[k]**2)/512);power.forEach((x,k)=>spectrum[k]+=x);spec.push(power.map(x=>10*Math.log10(x+1e-12)));banks.forEach((b,bi)=>{const logs=b.map(w=>Math.log(Math.max(w.reduce((s,x,k)=>s+x*power[k],0),1e-12)));const c=Array.from({length:20},(_,k)=>Math.sqrt(2/40)*logs.reduce((s,v,j)=>s+v*Math.cos(Math.PI*(k+1)*(j+.5)/40),0));(bi?lfcc:mfcc).push(c);});
 // Normalized autocorrelation pitch proxy on a 40 ms frame.
 const plen=Math.min(Math.round(.04*sr),n-start),minLag=Math.floor(sr/400),maxLag=Math.min(Math.ceil(sr/60),plen-2);let best=0,lag=0;for(let l=minLag;l<=maxLag;l++){let xy=0,xx=0,yy=0;for(let j=0;j<plen-l;j++){const a=samples[start+j],b=samples[start+j+l];xy+=a*b;xx+=a*a;yy+=b*b;}const corr=xy/Math.sqrt(xx*yy||1);if(corr>best){best=corr;lag=l;}}pitch.push({time:start/sr,hz:best>.72&&lag?sr/lag:null});count++;}
 const summarize=matrix=>Array.from({length:20},(_,k)=>{const vals=matrix.map(x=>x[k]),mean=vals.reduce((s,x)=>s+x,0)/vals.length;return {coefficient:k+1,mean,std:Math.sqrt(vals.reduce((s,x)=>s+(x-mean)**2,0)/vals.length)};});const voiced=pitch.filter(x=>x.hz!==null),frequencies=voiced.map(x=>x.hz).sort((a,b)=>a-b);
 return {duration:n/sr,sample_rate:sr,peak,rms_dbfs:20*Math.log10(Math.sqrt(sum/n)),clipping:clip/n,zcr:zcr/n,voiced_ratio:voiced.length/pitch.length,f0_median:frequencies.length?frequencies[Math.floor(frequencies.length/2)]:null,waveform,spectrum:spectrum.map(x=>10*Math.log10(x/count+1e-12)),spectrogram:spec,pitch,mfcc:summarize(mfcc),lfcc:summarize(lfcc),sampled_frames:count,total_frames:frameCount,frame_stride:stride,method:'Browser exploratory: 16 kHz mono, 25 ms Hann, hop 10 ms, FFT 512, 40 filters, DCT-II c1–c20; autocorrelation pitch proxy 60–400 Hz. Not the frozen v4/v5 model features.'};
}
